var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/1234/projects/%7Bproject_id%7D/equipment_register/associate"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
    },
    Content = new StringContent("{\"ids\":[\"01J3F5HDS3A3KE980C4H7HW3KQ\"]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
